function compute(inputs) {
  const V0 = inputs.V0;
  const R = inputs.R;
  const C = inputs.C;
  const tau = R * C;
  const tMax = 5 * tau;
  const numPoints = 100;
  const t = [];
  const V = [];
  for (let i = 0; i <= numPoints; i++) {
    const ti = (i / numPoints) * tMax;
    t.push(ti);
    V.push(V0 * (1 - Math.exp(-ti / tau)));
  }
  const Vtau = V0 * (1 - Math.exp(-1));
  const V5tau = V0 * (1 - Math.exp(-5));
  const series = {
    x: t,
    lines: [{ name: 'V(t)', y: V }],
    marker: { x: tau, y: Vtau }
  };
  const table = {
    columns: ['Quantity', 'Value'],
    rows: [
      ['V0 (V)', V0],
      ['R (Ω)', R],
      ['C (F)', C],
      ['τ = RC (s)', tau],
      ['V(τ) (V)', Vtau],
      ['V(5τ) (V)', V5tau]
    ]
  };
  const insight = `At t = τ = ${tau.toFixed(3)} s, V = ${Vtau.toFixed(3)} V (${(100 * (1 - Math.exp(-1))).toFixed(1)}% of V0). At t = 5τ, V = ${V5tau.toFixed(3)} V (${(100 * (1 - Math.exp(-5))).toFixed(1)}% of V0).`;
  return { series, table, insight };
}
